/** Р-209, Р-210: после чего поднята цена без наблюдения конкурентов */
const RAISE_AFTER_TEXT: Readonly<Record<FloorRaiseReason, string>> = {
  // Шаг 102: рост себестоимости называет фраза впереди (costRaise), а не хвост «после чего»
  COST_UPDATE: '',
  FLOOR_RECHECK: ' after the floor was recomputed before sending (current cost, fees, exchange rate and VAT)',
  FX_UPDATE: ' after the ECB exchange rate changed',
  BOUNDS_UPDATE: ' after your minimum or maximum price changed',
  GUARDRAIL_UPDATE: ' after your minimum margin or step limit changed',
  VAT_UPDATE: ' after the VAT rate changed',
  CLEARANCE_ENDED: ' after clearance ended',
};
const raiseAfter = (f: Fmt): string => RAISE_AFTER_TEXT[String(f.get('after') ?? '') as FloorRaiseReason] ?? '';
/** Шаг 102 [Р-227]: рост себестоимости поднял пол — словами владельца, впереди фразы; граница пола — словами */
const costRaise = (f: Fmt): string => (f.get('after') === 'COST_UPDATE' ? 'Unit cost increased: floor moved up. ' : '');
const floorWord = (f: Fmt): string => ({ margin_floor: 'your margin floor', break_even: 'break-even', clearance: 'your clearance floor' } as Record<string, string>)[String(f.get('bound'))] ?? 'your minimum price';
const deviation = (f: Fmt) => opt(f, 'deviationBp', () => ` by ${f.bp('deviationBp')}`);

/** Шаг 101 [Р-226]: фильтр «Compete with», ориентир и почему Buy Box не участвовал — словами */
const COMPETE_WITH_TEXT: Readonly<Record<string, string>> = { CHANNEL: 'FBA only', MERCHANT: 'FBM only' };
const competeWithText = (f: Fmt) => COMPETE_WITH_TEXT[String(f.get('competeWith'))] ?? noValue;
const BUYBOX_UNUSED_TEXT: Readonly<Record<string, string>> = {
  ABSENT: 'the channel gave no Buy Box price', SELF: 'the Buy Box is yours', UNKNOWN: 'the channel does not name its holder',
  EXCLUDED: 'its holder is excluded by your filter', NO_SHIPPING: 'its shipping price is unknown',
};
const anchorLine = (f: Fmt): string => {
  const [name, other] = f.get('anchorUsed') === 'BUYBOX' ? ['Buy Box', 'lowest'] : ['lowest', 'Buy Box'];
  const note = f.has('otherAnchorMinor')
    ? (f.get('otherAnchorMinor') === f.get('anchorMinor') ? ` (${other} ${f.money('otherAnchorMinor')} is the same)` : ` (lower than ${other} ${f.money('otherAnchorMinor')})`)
    : f.has('buyboxUnused') ? ` (Buy Box not used: ${BUYBOX_UNUSED_TEXT[String(f.get('buyboxUnused'))] ?? noValue})`
    : f.get('anchorSetting') === 'LOWER_OF_TWO' ? ' (no lowest offer to compare)' : '';
  return `Anchor: ${name} ${f.money('anchorMinor')}${note}`;
};

const reasons: Record<AnyReasonCode, Template> = {
  INVALID_AMOUNT: (f) => `Snapshot rejected: invalid amount in ${f.value('field')}${opt(f, 'offerRank', () => ` of offer #${f.count('offerRank')}`)}${opt(f, 'valueMinor', () => `: ${f.money('valueMinor')}`)}.`,
  CURRENCY_MISMATCH: (f) => `Snapshot rejected: ${f.value('field')} is in ${f.raw('actual')}, the offer is priced in ${f.raw('expected')}.`,
  PRICE_BASIS_MISMATCH: (f) => `Snapshot rejected: ${f.value('field')} is ${f.value('actual')}, prices of this storefront are ${f.value('expected')}.`,
  INCONSISTENT_SNAPSHOT: (f) => {
    switch (f.get('inconsistency')) {
      case 'OFFER_TOTAL_NOT_PRICE_PLUS_SHIPPING':
        return `Snapshot rejected: offer #${f.count('offerRank')} totals ${f.money('totalMinor')}, but price ${f.money('offerPriceMinor')} plus shipping ${f.money('shippingMinor')} is different.`;
      case 'MORE_OFFERS_THAN_TOP_N':
        return `Snapshot rejected: it lists ${f.count('offers')} offers although the channel promised the top ${f.count('topN')}.`;
      default:
        return `Snapshot rejected: the Buy Box ${f.money('buyboxMinor')} differs from the rank 1 offer ${f.money('rankOneMinor')}.`;
    }
  },
  SNAPSHOT_FROM_FUTURE: (f) => `Snapshot rejected: observed ${f.seconds('skewSeconds')} in the future (allowed ${f.seconds('maxSkewSeconds')}).`,
  SNAPSHOT_TOO_OLD: (f) => `Snapshot rejected: the data is ${f.seconds('ageSeconds')} old (limit ${f.seconds('maxAgeSeconds')}).`,
  OUT_OF_ORDER: (f) => `Snapshot skipped: a newer snapshot from ${f.when('lastAcceptedAt')} is already in use.`,
  CHANNEL_HALTED: (f) => {
    const since = opt(f, 'haltedAt', () => ` since ${f.when('haltedAt')}`);
    const why = opt(f, 'haltReason', () => ` (${f.value('haltReason')})`);
    switch (f.get('stage')) {
      case 'INPUT': return `Competitor data of this storefront is halted${since}${why}; the snapshot is not used until it resumes.`;
      case 'GATE': return `Held: prices derived from competitor data are halted on this storefront${since}${why}.`;
      case 'DISPATCH': return 'Not sent: the storefront was halted for competitor-derived prices before dispatch.';
      default: return 'Refused by the database: the storefront is halted for competitor-derived prices.';
    }
  },
  CHANNEL_MASS_SHIFT: (f) => `Competitor-derived prices halted: ${f.count('sameDirection')} of ${f.count('products')} products moved ${f.value('direction')} by almost the same factor ${f.ratio('medianFactor')} within ${f.minutes('windowMinutes')} (spread ${f.ratio('spread')}) — this looks like a parsing error.`,
  UNIT_SCALE_X100: (f) => `Snapshot rejected: ${f.value('field')} ${f.money('valueMinor')} is exactly 100× the reference ${f.money('referenceMinor')} (${f.value('anchor')}) — likely a decimal-point error.`,
  UNIT_SCALE_X0_01: (f) => `Snapshot rejected: ${f.value('field')} ${f.money('valueMinor')} is exactly 1/100 of the reference ${f.money('referenceMinor')} (${f.value('anchor')}) — likely a decimal-point error.`,
  PRICE_BELOW_COST_ANCHOR: (f) => `Snapshot rejected: ${f.value('field')} ${f.money('valueMinor')} is below ${f.ratio('limit')} of the unit cost ${f.money('costMinor')} — implausible.`,
  PRICE_ABOVE_COST_ANCHOR: (f) => `Snapshot rejected: ${f.value('field')} ${f.money('valueMinor')} is more than ${f.ratio('limit')} the unit cost ${f.money('costMinor')} — implausible.`,
  SNAPSHOT_INTERNAL_OUTLIER: (f) => `Snapshot rejected: an offer at ${f.money('valueMinor')} is more than ${f.ratio('outlierFactor')} away from the median ${f.money('medianMinor')} of ${f.count('offers')} offers.`,
  CROSS_CHANNEL_MISMATCH: (f) => `Snapshot rejected: ${f.value('field')} ${f.money('valueMinor')} is ${f.ratio('ratio')} away from the same EAN on ${f.list('referenceStorefronts')} (${f.money('referenceMinor')}, limit ${f.ratio('limit')})${opt(f, 'fxRateDate', () => `, converted at the ECB rate of ${f.date('fxRateDate')}`)}.`,
  OUTSIDE_HISTORY_BAND: (f) => `Snapshot rejected: ${f.value('field')} ${f.money('valueMinor')} is outside ${f.money('bandLowMinor')}–${f.money('bandHighMinor')} seen over ${f.count('days')} days.`,
  NO_PLAUSIBILITY_ANCHOR: (f) => `Snapshot not used: nothing to check it against (${f.count('competitorOffers')} competitor offers, ${f.count('historyDays')} days of history, unit cost ${f.get('costDeclared') ? 'declared' : 'missing'}). Declare the unit cost — it is the primary anchor.`,
  OWN_PRICE_DEVIATION: (f) => `Warning: ${f.value('field')} ${f.money('valueMinor')} differs from our price ${f.money('ourPriceMinor')} by ${f.ratio('ratio')}; the snapshot was accepted.`,
  SELF_OFFER_DIVERGENCE: (f) => `Our offer shows ${f.money('valueMinor')} in the channel, but our price is ${f.money('ourPriceMinor')} — a divergence case was opened.`,
  INTERNAL_OUTLIER_IGNORED: (f) => `Warning: an offer at ${f.money('valueMinor')} is far from the median ${f.money('medianMinor')}, but the strategy does not use it.`,
  MARKET_SHIFT_DISPERSED: (f) => `Market event: ${f.count('sameDirection')} of ${f.count('products')} products moved ${f.value('direction')} with different factors (spread ${f.ratio('spread')}); prices keep working.`,
  MARKET_SHIFT_SINGLE_SELLER: (f) => `Market event: one seller (${f.raw('seller')}) moved the prices of ${f.count('sameDirection')} products; prices keep working.`,
  CROSS_CHANNEL_FX_UNAVAILABLE: (f) => `The same-EAN check skipped ${f.value('channel')} ${f.raw('marketplace')}: its price is in ${f.raw('currency')} and there is no ECB rate to ${f.raw('expected')} (${f.value('cause')}).`,

  FIXED_PRICE: (f) => `Fixed price of the strategy: ${f.money('targetMinor')}.`,
  MARGIN_TARGET: (f) => `Price for the target margin ${f.bp('marginBp')}: ${f.money('targetMinor')}.`,
  BUYBOX_MATCH: (f) => `Match the Buy Box ${f.money('buyboxMinor')}: ${f.money('targetMinor')}.`,
  BUYBOX_UNDERCUT: (f) => `Undercut the Buy Box ${f.money('buyboxMinor')} by ${f.money('undercutMinor')}: ${f.money('targetMinor')}.`,
  LOWEST_MATCH: (f) => `Match the lowest price ${f.get('scope') === 'MARKET' ? 'of the market' : 'among the visible offers'} ${f.money('lowestMinor')}: ${f.money('targetMinor')}.`,
  LOWEST_UNDERCUT: (f) => `Undercut the lowest price ${f.money('lowestMinor')} by ${f.money('undercutMinor')}: ${f.money('targetMinor')}.`,
  CAPPED_AT_MIN_PRICE: (f) => `Target ${f.money('targetMinor')} is below your minimum price — capped at ${f.money('minMinor')}.`,
  CAPPED_AT_MAX_PRICE: (f) => `Target ${f.money('targetMinor')} is above your maximum price — capped at ${f.money('maxMinor')}.`,
  CAPPED_AT_MARGIN_FLOOR: (f) => `Target ${f.money('targetMinor')} is below your margin floor ${f.money('floorMinor')} (margin ${f.bp('minMarginBp')}) — set to the margin floor.`,
  // Шаг 102 [Р-227]: режим распродажи — пол ниже безубыточности намеренно; убыток на штуку называется суммой
  CLEARANCE_FLOOR: (f) => (f.has('lossPerUnitMinor') ? `Clearance mode: floor ${f.money('floorMinor')} is below break-even ${f.money('breakEvenMinor')} (−${f.money('lossPerUnitMinor')} per piece).` : f.has('breakEvenMinor') ? `Clearance mode: floor ${f.money('floorMinor')}, break-even ${f.money('breakEvenMinor')}.` : `Clearance mode: floor ${f.money('floorMinor')} — break-even is not computed.`),
  CAPPED_AT_CLEARANCE_FLOOR: (f) => `Target ${f.money('targetMinor')} is below your clearance floor ${f.money('floorMinor')} — set to the clearance floor.`,
  CLEARANCE_BELOW_CHANNEL_MIN: (f) => `Your clearance floor ${f.money('floorMinor')} is below the channel's own minimum ${f.money('channelMinMinor')}: prices below it are sent, as you confirmed, and the channel may deactivate this offer.`,
  RAISED_TO_FLOOR: (f) => costRaise(f) + (f.get('bound') === 'break_even'
    ? `Your price ${f.money('currentMinor')} was below break-even — raised to break-even ${f.money('floorMinor')}${raiseAfter(f)}.`
    : f.get('bound') === 'clearance'
    ? `Your price ${f.money('currentMinor')} was below your clearance floor — raised to ${f.money('floorMinor')}${raiseAfter(f)}.`
    : f.get('bound') === 'margin_floor'
    ? `Your price ${f.money('currentMinor')} was below your margin floor — raised to your margin floor ${f.money('floorMinor')}${raiseAfter(f)}${opt(f, 'minMarginBp', () => ` (margin ${f.bp('minMarginBp')})`)}.`
    : `Your price ${f.money('currentMinor')} was below your minimum price — raised to ${f.money('floorMinor')}${raiseAfter(f)}.`),
  RAISED_TOWARD_FLOOR: (f) => costRaise(f) + `Your price ${f.money('currentMinor')} is below ${floorWord(f)} ${f.money('floorMinor')} — raised one step${raiseAfter(f)}, as far as the step limit of ${f.bp('stepLimitBp')} allows; about ${f.count('stepsLeft')} more ${f.get('stepsLeft') === 1 ? 'step' : 'steps'} to the floor.`,
  ALREADY_AT_TARGET: (f) => `The price already equals the target ${f.money('targetMinor')}.`,
  WITHIN_DEADBAND: (f) => `The difference ${f.money('deltaMinor')} is below the threshold ${f.money('deadbandMinor')} — the price stays.`,
  // Р-171 (шаг 41): то же предложение уже удержано тенью — повторять его незачем
  LADDER_PACED: (f) => `Your price ${f.money('currentMinor')} is below the floor ${f.money('floorMinor')}; the next step toward it comes at ${f.when('nextStepAt')} at the earliest — one step per scheduled recompute, competitor moves do not speed it up.`,
  SHADOW_ALREADY_PROPOSED: (f) => `Nothing sent: the shadow mode already holds this very price (${f.money('heldMinor')}), so the engine does not propose it again. Prices reach your store only after sending prices is switched on.`,
  ALREADY_WINNING_BUYBOX: () => 'We already win the Buy Box — the price stays.',
  // Шаг 97 [Р-219, Р-221]: «Win the Buy Box» и держатель, которого канал не называет
  BUYBOX_WIN_TARGET: (f) => `The Buy Box costs the buyer ${f.money('winnerLandedMinor')} with shipping; ${f.money('undercutMinor')} below it${(f.get('handicapMinor') as number) > 0 ? `, ${f.money('handicapMinor')} more because the channel fulfils the winner and not you` : ''}, minus your shipping ${f.money('ownShippingMinor')}: ${f.money('targetMinor')}.`,
  CREEP_UP: (f) => `You hold the Buy Box — raised one step of ${f.bp('creepStepBp')} from ${f.money('fromMinor')} to ${f.money('toMinor')}.`,
  CREEP_STEP_BACK: (f) => `The Buy Box was lost at ${f.money('lostAtMinor')} right after a raise — back to ${f.money('backToMinor')}, the last price that held it; raises pause until ${f.when('pausedUntil')}.`,
  CAPPED_AT_CREEP_CEILING: (f) => `While raises are paused, ${f.money('ceilingMinor')} — the price at which the Buy Box was lost — is the ceiling: the target ${f.money('targetMinor')} is kept below it.`,
  BUYBOX_HOLDER_UNKNOWN: (f) => `This channel does not say who holds the Buy Box. Your price ${f.money('currentMinor')} equals the Buy Box price ${f.money('buyboxMinor')}, so the Buy Box may be yours — undercutting it would chase your own price down; the price stays.`,
  // Шаг 101 [Р-226]: ориентир, фильтр и «никого после фильтра»
  ANCHOR_UNDERCUT: (f) => `${anchorLine(f)}; ${(f.get('undercutMinor') as number) > 0 ? `${f.money('undercutMinor')} below it` : 'matched'}${(f.get('handicapMinor') as number) > 0 ? `, ${f.money('handicapMinor')} more because the channel fulfills that offer and not you` : ''}${(f.get('ownShippingMinor') as number) > 0 ? `, minus your shipping ${f.money('ownShippingMinor')}` : ''}: ${f.money('targetMinor')}.`,
  COMPETITORS_FILTERED: (f) => `Compete with: ${competeWithText(f)} — considered ${f.count('offersConsidered')} of ${f.count('offersTotal')} ${f.get('offersTotal') === 1 ? 'offer' : 'offers'}${(f.get('offersUnknown') as number) > 0 ? `; ${f.count('offersUnknown')} excluded: fulfillment unknown` : ''}.`,
  NO_ELIGIBLE_COMPETITORS: (f) => `Compete with: ${competeWithText(f)} — ${f.get('buyboxHolder') === 'EXCLUDED' ? 'the Buy Box holder is excluded by your filter, and this strategy follows the Buy Box only'
    : f.get('buyboxHolder') === 'UNKNOWN' ? 'the channel does not name the fulfillment of the Buy Box holder, and this strategy follows the Buy Box only'
    : `no competitor passes your filter (${f.count('offersTotal')} ${f.get('offersTotal') === 1 ? 'offer' : 'offers'}${(f.get('offersUnknown') as number) > 0 ? `, ${f.count('offersUnknown')} of them with fulfillment unknown` : ''})`}. The price stays: your filter is kept, not widened to all competitors.`,
  CREEP_PACED: (f) => `You hold the Buy Box at ${f.money('currentMinor')}; the next raise comes at ${f.when('nextStepAt')} at the earliest — one step per scheduled recompute.`,
  CREEP_PAUSED: (f) => `You hold the Buy Box at ${f.money('currentMinor')}; raises are paused until ${f.when('pausedUntil')} after the Buy Box was lost on a raise.`,
  CREEP_AT_MAX: (f) => `You hold the Buy Box at ${f.money('currentMinor')}, your maximum price ${f.money('maxMinor')} — no raise.`,
  NO_COMPETITOR_OFFERS: () => 'No competitor offers — nothing to follow.',
  TARGET_OUTSIDE_BOUNDS_HOLD: (f) => `Target ${f.money('targetMinor')} is outside ${f.money('minMinor')}–${f.money('maxMinor')}; the strategy is set to keep the price.`,
  CHANNEL_BOUNDS_HOLD: (f) => (f.get('side') === 'MAX'
    ? `Price ${f.money('targetMinor')} is above the channel's own maximum ${f.money('channelMaxMinor')} — the channel would deactivate this offer, so the price was not sent.`
    : `Price ${f.money('targetMinor')} is below the channel's own minimum ${f.money('channelMinMinor')} — the channel would deactivate this offer, so the price was not sent.`),
  COMPETITOR_REQUIREMENT_NOT_MET: (f) => `Strategy not evaluated: the channel data does not provide ${f.list('unmet')}${opt(f, 'requiredCompleteness', () => ` (needs ${f.value('requiredCompleteness')}${opt(f, 'requiredN', () => ` ${f.count('requiredN')}`)}, got ${f.has('actualCompleteness') ? f.value('actualCompleteness') : noValue}${opt(f, 'actualN', () => ` ${f.count('actualN')}`)})`)}${opt(f, 'ageSeconds', () => `; data age ${f.seconds('ageSeconds')}${opt(f, 'maxStalenessSeconds', () => `, limit ${f.seconds('maxStalenessSeconds')}`)}`)}.`,
  COST_INPUTS_MISSING: (f) => `Strategy not evaluated: ${f.value('missing')} is missing.`,
  MARGIN_UNATTAINABLE: (f) => `The target margin ${f.bp('marginBp')} cannot be reached: fee ${f.bp('feeRateBp')}, fixed fee ${f.money('fixedFeeMinor')}, unit cost ${f.money('unitCostMinor')}${opt(f, 'vatRateBp', () => `, VAT ${f.bp('vatRateBp')}`)}.`,
  BOUNDS_INVALID: (f) => `Strategy not evaluated: the bounds ${f.money('minMinor')}–${f.money('maxMinor')} are invalid.`,
  ENGINE_CURRENCY_MISMATCH: (f) => `Strategy not evaluated: ${f.value('source')} is in ${f.raw('actual')}, the offer in ${f.raw('expected')}.`,
  INVALID_STRATEGY_PARAMS: (f) => `Strategy not evaluated: the setting ${f.value('param')}${opt(f, 'settingMinor', () => ` ${f.money('settingMinor')}`)}${opt(f, 'settingBp', () => ` ${f.bp('settingBp')}`)} must be ${f.value('allowed')}.`,

  // Р-208: ступень лестницы ниже пола — одобрена как шаг к полу, а не «в границах»
  APPROVED: (f) => (Number(f.get('finalMinor')) < Number(f.get('floorMinor'))
    ? `Step to ${f.money('finalMinor')} toward the floor ${f.money('floorMinor')} approved; the price is still below the floor.`
    : `Price ${f.money('finalMinor')} approved within ${f.money('floorMinor')}–${f.money('ceilingMinor')}.`),
  NO_CHANGE: () => 'No price change — the decision is recorded without sending.',
  BELOW_MIN_PRICE: (f) => f.get('floor') === 'CLEARANCE' ? `Rejected: ${f.money('proposedMinor')} is below your clearance floor ${f.money('minMinor')}${deviation(f)}.` : `Rejected: ${f.money('proposedMinor')} is below your minimum price ${f.money('minMinor')}${deviation(f)}.`,
  BELOW_MARGIN_FLOOR: (f) => `Rejected: ${f.money('proposedMinor')} is below the minimum-margin floor ${f.money('floorMinor')}${opt(f, 'minMarginBp', () => ` (margin ${f.bp('minMarginBp')})`)}${deviation(f)}.`,
  ABOVE_MAX_PRICE: (f) => `Rejected: ${f.money('proposedMinor')} is above your maximum price ${f.money('maxMinor')}${deviation(f)}.`,
  // Шаг 102 [Р-227]: пол выше потолка — законное состояние; квитанция говорит, что цены заморожены и что сделать
  BOUND_UNRESOLVABLE: (f) => f.get('cause') === 'MARGIN_FLOOR_ABOVE_MAX_PRICE'
    ? `Rejected: ${f.value('bound')} is above your maximum price${opt(f, 'minMarginBp', () => ` (minimum margin ${f.bp('minMarginBp')})`)} — no price fits, so prices are frozen. Raise the maximum price or enable clearance. Nothing is sent.`
    : `Rejected: ${f.value('bound')} cannot be computed — ${f.value('cause')}${opt(f, 'boundCurrency', () => ` (bound ${f.raw('boundCurrency')} ${f.value('boundBasis')}, offer ${f.raw('scopeCurrency')} ${f.value('scopeBasis')})`)}${opt(f, 'minMarginBp', () => ` (minimum margin ${f.bp('minMarginBp')})`)}. Nothing is sent.`,
  STEP_LIMIT: (f) => `Held: the change from ${f.money('currentMinor')} to ${f.money('proposedMinor')} is ${f.bp('stepBp')}, the allowed step is ${f.bp('limitBp')}.`,
  CHANGE_RATE_LIMIT: (f) => `Held: already ${f.count('changes')} changes in the last hour, the limit is ${f.count('limit')}.`,
  INTENT_EXPIRED: (f) => `Rejected: the proposed price waited ${f.seconds('waitedSeconds')} and expired at ${f.when('expiresAt')}.`,
  INTENT_INVALID: (f) => `Rejected: internal error — ${f.value('problem')}.`,
  SCOPE_NOT_ACTIVE: (f) => `Held: the offer is ${f.value('status')} with pricing mode ${f.value('mode')}${opt(f, 'blockedByErrorCode', () => ` since ${f.when('blockedSince')} because of ${f.value('blockedByErrorCode')}`)}${opt(f, 'action', () => `. ${f.value('action')}`)}.`,
  PRICING_STOPPED: (f) => {
    switch (f.get('stage')) {
      case 'GATE': return `Held: pricing is stopped for ${f.value('scope')} since ${f.when('stoppedAt')} — no price changes at all until a person resumes it.`;
      case 'DISPATCH': return 'Not sent: pricing was stopped by a person before dispatch.';
      default: return 'Refused by the database: pricing is stopped by a person.';
    }
  },
  INTERNAL_BOUND_VIOLATION: (f) => `Rejected: internal error — ${f.value('check')} found ${f.money('amountMinor')} outside ${f.money('floorMinor')}–${f.money('ceilingMinor')}; an alert was raised.`,

  // Р-131 (step 27): the requirement is shown when the seller tries to enable the strategy, not as silently missing decisions
  COST_REQUIRED: (f) => `Repricing not enabled: without the declared unit cost there is nothing to check competitor prices against${opt(f, 'cause', () => ` — ${f.value('cause')}`)}; enter the unit cost.`,
  MIN_PRICE_MISSING: () => 'Repricing not enabled: your minimum price is not set.',
  MAX_PRICE_MISSING: () => 'Repricing not enabled: your maximum price is not set.',
  BOUNDS_INVERTED: (f) => `Repricing not enabled: your minimum price ${f.money('minMinor')} is above your maximum price ${f.money('maxMinor')}.`,
  BOUND_CURRENCY_MISMATCH: (f) => `Repricing not enabled: ${f.value('bound')} is ${f.has('cause') ? f.value('cause') : 'inconsistent'}${opt(f, 'boundCurrency', () => ` (${f.raw('boundCurrency')} ${f.has('boundBasis') ? f.value('boundBasis') : ''})`)}; the offer is ${f.raw('scopeCurrency')} ${f.value('scopeBasis')}.`,
  SCOPE_NOT_ENGINE: () => 'Repricing is off for this offer.',
  NO_SCOPE_FOR_PRODUCT: () => 'The snapshot does not belong to any of our offers with repricing.',
  WRITE_BLOCKED_BY_BOUND_RECHECK: (f) => f.get('violated') === 'FLOOR_UNRESOLVABLE'
    ? `Not sent: at dispatch the floor could not be computed again — ${f.value('cause')}.`
    : `Not sent: at dispatch ${f.money('amountMinor')} is ${f.get('violated') === 'FLOOR' ? `below the floor ${f.money('floorMinor')}${opt(f, 'marginFloorMinor', () => ` (margin floor ${f.money('marginFloorMinor')} at minimum margin ${f.bp('minMarginBp')}, recomputed from current cost, fee, rate and VAT)`)}` : `above the ceiling ${f.money('ceilingMinor')}`}.`,
  WRITE_NOT_ACCEPTED_BY_CHANNEL: (f) => `The channel refused the price: ${f.value('status')}${opt(f, 'httpStatus', () => ` (HTTP ${f.raw('httpStatus')})`)}${opt(f, 'channelCode', () => `, channel code ${f.raw('channelCode')}`)}.`,
  BOUNDS_VERSION_CHANGED: (f) => `${f.has('changed') ? f.list('changed') : 'The decision context'} changed while the decision was being made (attempt ${f.count('attempt')})${f.get('oldMinMinor') !== f.get('newMinMinor') && f.has('newMinMinor') ? ` — your minimum price ${f.money('oldMinMinor')} → ${f.money('newMinMinor')}` : ''}${f.get('oldMaxMinor') !== f.get('newMaxMinor') && f.has('newMaxMinor') ? ` — your maximum price ${f.money('oldMaxMinor')} → ${f.money('newMaxMinor')}` : ''}; the price was recalculated.`,
  DIVERGENCE_CASE_OPENED: (f) => `Divergence case opened: the channel shows ${f.money('observedMinor')}, we expect ${f.money('expectedMinor')}.`,
  HALT_AUTO_RELEASED: (f) => `The halt was released automatically: a fresh sample of ${f.count('sampleSize')} products passed.`,
  HALT_REVIEW_FAILED: (f) => `The halt stays: a sample of ${f.count('sampleSize')} products had ${f.count('failed')} failures${opt(f, 'nextReviewAt', () => `; next check ${f.when('nextReviewAt')}`)}.`,
  HALT_MANUALLY_RELEASED: (f) => `The halt was released manually${opt(f, 'note', () => `: “${f.raw('note')}”`)}.`,
  MARGIN_WITHOUT_COST: (f) => {
    const needs = String(f.get('requiredBy') ?? '').split(',').filter(Boolean).map((r) => (r === 'STRATEGY' ? `the ${f.value('strategyType')} strategy` : `the minimum margin ${f.bp('minMarginBp')}`));
    return `Warning: ${needs.join(' and ')} ${needs.length > 1 ? 'need' : 'needs'} the unit cost, but ${f.value('cause')}. Every price would be rejected until it is available.`;
  },
  STRATEGY_MISSING: () => 'Repricing not enabled: the offer has no strategy.',

  WRITE_SUPERSEDED_BY_NEWER_VERSION: (f) => `Not sent: a newer price (version ${f.count('newerVersion')}) replaced it before dispatch.`,
  WRITE_RETRIES_EXHAUSTED: (f) => `Not sent: the channel failed ${f.count('attempts')} times (${f.value('code')}); an alert was raised.`,
  WRITE_PRICING_MODE_CHANGED: (f) => `Not sent: the pricing mode changed to ${f.value('mode')}.`,
  WRITE_EDIT_BUDGET_EXHAUSTED: (f) => `Not sent: the daily edit budget is used up${f.has('used') && f.has('limit') ? ` (${f.count('used')} of ${f.count('limit')})` : ''}${opt(f, 'budgetDay', () => ` for ${f.date('budgetDay')}`)}${opt(f, 'timeZone', () => ` (${f.raw('timeZone')})`)}${opt(f, 'resetsAt', () => `; it renews at ${f.when('resetsAt')}`)}.`,
  // Р-169 (шаг 41): аккаунт ушёл в тень, пока запись была в полёте — повтор в канал не идёт
  WRITE_HELD_IN_SHADOW: (f) => `Not sent: this channel account is in shadow mode, so nothing is sent to your store. The engine keeps computing prices; to send them, start sending prices on the Shadow mode screen.`,
  QUANTITY_WRITES_REVOKED: (f) => `Not sent: stock updates for the channel account ${f.raw('channelAccountId')} were revoked, so no stock is sent to your store. Stock sync switches on again only after a new confirmation that no other tool manages stock there.`,
  WRITE_BUDGET_DAY_UNCONFIRMED: (f) => `Not sent: the retry needs the edit budget of the current day, but the day boundary of storefront ${f.raw('marketplace')} is not confirmed. This update was dropped; a new price decision is possible once the storefront time zone is confirmed.`,
  CHANNEL_DISTRUSTED: (f) => `All prices held (${f.value('stage')}): we do not trust how the channel applies our prices${opt(f, 'distrustReason', () => ` — ${f.value('distrustReason')}`)}${opt(f, 'detectedAt', () => ` since ${f.when('detectedAt')}`)}. A fixed or margin price would take the same broken path. Only a person can release this.`,
  CHANNEL_PRICE_BASIS_MISMATCH: (f) => `All prices on storefront ${f.raw('marketplace')} halted: we sent ${f.money('sentMinor')}, buyers see ${f.money('observedMinor')} — exactly the VAT rate ${f.bp('vatRateBp')} ${f.value('basisError')}. The channel uses a different price basis than ours; every further price would be wrong by the same share. Check the price settings of the channel account and release the distrust manually.`,
  WRITE_QUEUED_BEHIND_IN_FLIGHT: () => 'Queued: the channel has not answered the previous update yet; this one is sent next.',
  WRITE_RETRY_SCHEDULED: (f) => `Temporary channel error (${f.value('code')}); attempt ${f.count('attempt')} after ${f.when('at')}.`,
  WRITE_OUTCOME_RECONCILED: (f) => `The outcome was unknown; reading back showed the price was ${f.value('result')}.`,
  WRITE_SCOPE_BLOCKED: (f) => `The offer is blocked: ${f.value('code')}. ${f.value('action')}.`,
};

const notes: Record<SanityNoteCode, Template> = {
  COST_NOT_DECLARED: () => 'unit cost is not declared',
  TOO_FEW_COMPETITOR_OFFERS: (f) => `${f.count('offers')} competitor offers, at least ${f.count('minOffers')} needed`,
  HISTORY_TOO_SHORT: (f) => `${f.count('days')} days of history, at least ${f.count('minHistoryDays')} needed`,
  HISTORY_AVAILABLE: (f) => `${f.count('days')} days of history`,
  NO_SCALE_REFERENCE: () => 'nothing to compare the scale with',
  SINGLE_SELLER_MARKET_EVENT: (f) => `one seller (${f.raw('seller')}) moved — market event`,
  DISPERSED_MARKET_EVENT: (f) => `different factors (spread ${f.ratio('spread')} above ${f.ratio('maxSpread')}) — market event`,
  SHIFT_BELOW_SHARE: (f) => `${f.count('sameDirection')} of ${f.count('products')} products moved, a halt needs ${f.count('minProducts')} and ${f.ratio('share')} of them`,
  SMALL_MOVE: (f) => `small move (below ${f.ratio('minFactor')})`,
  NO_PREVIOUS_SNAPSHOT: () => 'no previous snapshot',
  REFERENCES_CONVERTED_AT_ECB: (f) => `references converted ${f.raw('fxFrom')}→${f.raw('currency')} at the ECB rate of ${f.date('fxRateDate')}`,
  REFERENCES_WITHOUT_ECB_RATE: () => 'references in another currency without an ECB rate',
  NO_FRESH_CROSS_CHANNEL_REFERENCE: (f) => `no reference for the same EAN on another channel younger than ${f.seconds('maxAgeSeconds')}`,
};

/**
 * Шаг 68 (K11): заголовки заметок проверок входов. Без них «почему эта цена» показывал коды (`SMALL_MOVE`,
 * `NO_FRESH_CROSS_CHANNEL_REFERENCE`) вместо названия проверки
 */
const noteTitles: Record<SanityNoteCode, string> = {
  COST_NOT_DECLARED: 'Unit cost not declared',
  TOO_FEW_COMPETITOR_OFFERS: 'Too few competitor offers',
  HISTORY_TOO_SHORT: 'Price history too short',
  HISTORY_AVAILABLE: 'Price history available',
  NO_SCALE_REFERENCE: 'Nothing to check the scale against',
  SINGLE_SELLER_MARKET_EVENT: 'One seller moved',
  DISPERSED_MARKET_EVENT: 'The market moved unevenly',
  SHIFT_BELOW_SHARE: 'Too few products moved for a halt',
  SMALL_MOVE: 'Small move',
  NO_PREVIOUS_SNAPSHOT: 'No previous snapshot',
  REFERENCES_CONVERTED_AT_ECB: 'References converted at the ECB rate',
  REFERENCES_WITHOUT_ECB_RATE: 'References without an ECB rate',
  NO_FRESH_CROSS_CHANNEL_REFERENCE: 'No recent price on another channel',
};

/**
 * Шаг 68 (K11): причина стратегии, у которой суммы конкурента в объяснении уже не хранятся [Р-85]. Горячее намерение держит их
 * 3 дня, и «почему эта цена» берёт суммы оттуда; у решения старше — этот текст вместо заглушки на месте каждой суммы
 */
const keptNote = 'The decision keeps amounts taken from competitor prices for 3 days, so they are no longer shown; the full snapshot is linked in the snapshot step.';
/** Подрез — параметр стратегии: известен, пока его версия в справочнике (18 месяцев после замены, Р-91) */
const step = (f: Fmt) => (typeof f.get('undercutMinor') === 'number' ? f.money('undercutMinor') : 'the strategy step');
const reasonsWithoutChannel: Partial<Record<AnyReasonCode | SanityNoteCode, Template>> = {
  // Ревью шага 68, находка 4: суммы из цены конкурента решение держит 3 суток [Р-28]; сам снимок — 18 месяцев по ссылке шага снимка
  BUYBOX_MATCH: () => `Matched the Buy Box price seen at that moment. ${keptNote}`,
  BUYBOX_UNDERCUT: (f) => `Undercut the Buy Box price seen at that moment by ${step(f)}. ${keptNote}`,
  LOWEST_MATCH: (f) => `Matched the lowest price ${f.get('scope') === 'MARKET' ? 'of the market' : 'among the visible offers'} seen at that moment. ${keptNote}`,
  LOWEST_UNDERCUT: (f) => `Undercut the lowest price seen at that moment by ${step(f)}. ${keptNote}`,
  // Шаг 97: цель «Win the Buy Box» и цена, на которой Buy Box ушёл, выведены из данных канала [Р-85]
  BUYBOX_WIN_TARGET: (f) => `Went below the landed price of the Buy Box winner seen at that moment by ${step(f)}. ${keptNote}`,
  CREEP_STEP_BACK: (f) => `The Buy Box was lost right after a raise — back to ${f.money('backToMinor')}, the last price that held it; raises paused until ${f.when('pausedUntil')}.`,
  CAPPED_AT_CREEP_CEILING: () => 'While raises were paused, the target was kept below the price at which the Buy Box was lost.',
  BUYBOX_HOLDER_UNKNOWN: (f) => `This channel does not say who holds the Buy Box; your price ${f.money('currentMinor')} equalled the Buy Box price, so it may have been yours — the price stayed.`,
  // Шаг 101 [Р-226]: цены, число предложений, ориентир и фильтр — не вечные (ориентир и фильтр живут 18 месяцев рядом с подрезом)
  ANCHOR_UNDERCUT: (f) => `Went below the anchor of your strategy seen at that moment by ${step(f)}. ${keptNote}`,
  COMPETITORS_FILTERED: () => `Only competitors that passed your fulfillment filter were considered. ${keptNote}`,
  NO_ELIGIBLE_COMPETITORS: () => 'No competitor passed your fulfillment filter, so the price stayed; the filter was not widened to all competitors.',
  /**
   * Заметки и предупреждения проверки входов: их числа (сколько предложений, дней истории, какой продавец) — данные канала, и их нет ни
   * в вечном объяснении, ни в горячем намерении. Текст называет правило и его порог, а не пустое место
   */
  TOO_FEW_COMPETITOR_OFFERS: (f) => `fewer competitor offers than the ${f.count('minOffers')} needed`,
  HISTORY_TOO_SHORT: (f) => `less price history than the ${f.count('minHistoryDays')} days needed`,
  HISTORY_AVAILABLE: () => 'enough price history to check against',
  SINGLE_SELLER_MARKET_EVENT: () => 'one seller moved — market event',
  DISPERSED_MARKET_EVENT: (f) => `different factors (spread above ${f.ratio('maxSpread')}) — market event`,
  SHIFT_BELOW_SHARE: (f) => `fewer products moved than a halt needs (${f.count('minProducts')} and ${f.ratio('share')} of them)`,
  NO_PLAUSIBILITY_ANCHOR: (f) => `Snapshot not used: nothing to check it against (unit cost ${f.get('costDeclared') ? 'declared' : 'missing'}). Declare the unit cost — it is the primary anchor.`,
  OWN_PRICE_DEVIATION: (f) => `Warning: ${f.value('field')} differed from our price ${f.money('ourPriceMinor')} by more than ${f.ratio('limit')}; the snapshot was accepted.`,
  SELF_OFFER_DIVERGENCE: (f) => `Our offer showed a different price in the channel than our price ${f.money('ourPriceMinor')} — a divergence case was opened.`,
  INTERNAL_OUTLIER_IGNORED: () => 'Warning: one offer was far from the median of the snapshot, but the strategy does not use it.',
  MARKET_SHIFT_DISPERSED: () => 'Market event: products moved with different factors; prices keep working.',
  MARKET_SHIFT_SINGLE_SELLER: () => 'Market event: one seller moved the prices of several products; prices keep working.',
  // Цель стратегии выведена из цены конкурента [Р-85]: граница и решение — наши, их сумма остаётся
  CAPPED_AT_MIN_PRICE: (f) => `The target from competitor prices was below your minimum price — capped at ${f.money('minMinor')}.`,
  CAPPED_AT_MAX_PRICE: (f) => `The target from competitor prices was above your maximum price — capped at ${f.money('maxMinor')}.`,
  CAPPED_AT_MARGIN_FLOOR: (f) => `The target from competitor prices was below your margin floor — set to the margin floor ${f.money('floorMinor')} (margin ${f.bp('minMarginBp')}).`,
  CAPPED_AT_CLEARANCE_FLOOR: (f) => `The target from competitor prices was below your clearance floor — set to the clearance floor ${f.money('floorMinor')}.`,
  CLEARANCE_BELOW_CHANNEL_MIN: (f) => `Your clearance floor ${f.money('floorMinor')} was below the channel's own minimum: prices below it were sent, as you confirmed, and the channel could deactivate this offer. Amounts from the channel are kept with the decision for 3 days, so the minimum is no longer shown.`,
  ALREADY_AT_TARGET: () => 'The price already equalled the target.',
  WITHIN_DEADBAND: (f) => `The difference to the target was below the threshold ${f.money('deadbandMinor')} — the price stays.`,
  TARGET_OUTSIDE_BOUNDS_HOLD: (f) => `The target was outside ${f.money('minMinor')}–${f.money('maxMinor')}; the strategy is set to keep the price.`,
  CHANNEL_BOUNDS_HOLD: (f) => `The price was ${f.get('side') === 'MAX' ? 'above the channel\'s own maximum' : 'below the channel\'s own minimum'} — the channel would deactivate this offer, so it was not sent. Amounts from the channel are kept with the decision for 3 days, so they are no longer shown.`,
  COMPETITOR_REQUIREMENT_NOT_MET: () => 'Strategy not evaluated: the channel data did not give what the strategy needs.',
  ENGINE_CURRENCY_MISMATCH: (f) => `Strategy not evaluated: ${f.value('source')} was in another currency than the offer (${f.raw('expected')}).`,
  DIVERGENCE_CASE_OPENED: (f) => `Divergence case opened: the channel showed another price than the ${f.money('expectedMinor')} we expect.`,
  // Отказ Gate у цены из данных конкурента: предложенная цена и отклонение выведены из цены конкурента [Р-85]; граница — наша
  BELOW_MIN_PRICE: (f) => f.get('floor') === 'CLEARANCE' ? `Rejected: the proposed price was below your clearance floor ${f.money('minMinor')}.` : `Rejected: the proposed price was below your minimum price ${f.money('minMinor')}.`,
  BELOW_MARGIN_FLOOR: (f) => `Rejected: the proposed price was below the minimum-margin floor ${f.money('floorMinor')}${opt(f, 'minMarginBp', () => ` (margin ${f.bp('minMarginBp')})`)}.`,
  ABOVE_MAX_PRICE: (f) => `Rejected: the proposed price was above your maximum price ${f.money('maxMinor')}.`,
  STEP_LIMIT: (f) => `Held: the change from ${f.money('currentMinor')} was larger than the allowed step ${f.bp('limitBp')}.`,
  INTERNAL_BOUND_VIOLATION: (f) => `Rejected: internal error — ${f.value('check')} found the price outside ${f.money('floorMinor')}–${f.money('ceilingMinor')}; an alert was raised.`,
};

